contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint timeOffset, uint amount) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        uint beforeTime = c.pastBlockTime();
        uint callTime = beforeTime + 1 + (timeOffset % 1000);

        bool reverted;
        uint cBalBefore = address(c).balance;
        uint selfBalBefore = address(this).balance;
        uint blockNumBefore = block.number;

        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();

        if (reverted) {
            // Failed calls must not change the recorded timestamp or move any ether.
            assert(afterTime == beforeTime);
            assert(address(c).balance == cBalBefore);
            assert(address(this).balance == selfBalBefore);
        } else {
            // Successful calls update the timestamp and either keep the balance or,
            // when block.number %% 15 == 0, forward the whole prior balance to the caller.
            assert(afterTime == block.timestamp);
            assert(afterTime > beforeTime);
            assert(afterTime >= callTime);
            if (blockNumBefore % 15 == 0) {
                assert(address(c).balance == 0);
                assert(address(this).balance == selfBalBefore + cBalBefore);
            } else {
                assert(address(c).balance == cBalBefore + amount);
                assert(address(this).balance == selfBalBefore - amount);
            }
        }
    }
}

