    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        uint beforeBalance = address(c).balance;
        uint beforePast = c.pastBlockTime();

        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        if (reverted) {
            assert(block.timestamp <= beforePast);
            assert(afterPast == beforePast);
            assert(afterBalance == beforeBalance);
        } else {
            assert(block.timestamp > beforePast);
            assert(afterPast == block.timestamp);
            assert(afterBalance == beforeBalance + amount);
        }
    }

    receive() external payable {}
}

