contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 nextAmount) public payable {
        require(address(this).balance >= amount + nextAmount);

        uint256 beforeC = address(c).balance;
        uint256 beforeTime = c.pastBlockTime();

        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterC = address(c).balance;
        uint256 afterTime = c.pastBlockTime();

        if (!reverted) {
            assert(amount == 10 ether);
            assert(afterTime == block.timestamp);
            assert(afterTime > beforeTime);

            if (block.number % 15 == 0) {
                assert(afterC == 0);
                assert(address(this).balance >= beforeC + amount);
            } else {
                assert(afterC == beforeC + amount);
            }
        } else {
            assert(amount != 10 ether || block.timestamp <= beforeTime);
            assert(afterC == beforeC);
            assert(afterTime == beforeTime);
        }

        bool secondReverted;
        try c.call{value: nextAmount}("") {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint256 finalTime = c.pastBlockTime();
        if (!secondReverted) {
            assert(nextAmount == 10 ether);
            assert(finalTime == block.timestamp);
            assert(finalTime > beforeTime);
        }
    }

    receive() external payable {}
}

