contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint ts, uint amount) public payable {
        require(amount == 10 ether, "test must send exactly 10 ether");
        require(address(this).balance >= amount, "insufficient test balance");

        uint beforePast = c.pastBlockTime();
        require(ts > beforePast, "test chooser must select a future timestamp");

        // Set up timestamp state before the deciding fallback call.
        // We cannot assign block.timestamp, so use the chosen boundary indirectly:
        // the rule should hold for any amount/ts pair, and the contract tracks its own timestamp.
        require(ts > block.timestamp, "test chooser must select timestamp beyond current wall clock");

        bool reverted;
        try c.call{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();

        assert(
            reverted
                ? afterPast == beforePast
                : afterPast > beforePast && ts > beforePast && amount == 10 ether
        );
    }

    receive() external payable {}
}

