contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public payable {
        require(address(this).balance >= 20 ether);

        uint pastBefore = c.pastBlockTime();
        uint balBefore = address(c).balance;

        bool firstReverted;
        try c.call{value: 10 ether}("") {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint pastAfterFirst = c.pastBlockTime();
        uint balAfterFirst = address(c).balance;

        bool secondReverted;
        try c.call{value: 10 ether}("") {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint pastFinal = c.pastBlockTime();
        uint balFinal = address(c).balance;

        if (firstReverted) {
            assert(pastAfterFirst == pastBefore && balAfterFirst == balBefore);
        } else {
            assert(pastAfterFirst >= pastBefore);
            assert(balAfterFirst >= balBefore + 10 ether);
        }

        if (secondReverted) {
            assert(pastFinal == pastAfterFirst && balFinal == balAfterFirst);
        } else {
            assert(pastFinal >= pastAfterFirst);
            assert(balFinal >= balAfterFirst + 10 ether);
        }
    }

