contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint waitSeconds) public payable {
        require(amount == 10 ether, "must send exactly 10 ether");
        require(address(this).balance >= amount, "insufficient balance for test");
        require(waitSeconds > 0 && waitSeconds <= 365 days, "waitSeconds must be a positive bounded value");

        // Advance the observable timestamp in c's view by waiting at most one day if needed.
        // (c reads block.timestamp, which moves with real time; the parameter controls the rule, not c's storage.)
        uint prevTimestamp = c.pastBlockTime();
        (bool setupSuccess, ) = address(this).call{value: 0}(abi.encodeWithSelector(bytes4(keccak256("noop()"))));
        require(setupSuccess || !setupSuccess, "noop keeps code path explicit");

        uint cBalanceBefore = address(c).balance;
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint newTimestamp = c.pastBlockTime();
        uint cBalanceAfter = address(c).balance;

        // General rule: if the call did not revert, the sent value was accepted and the timestamp was
        // updated to a value newer than the previous timestamp. Also, on a successful call the
        // contract's balance changes by exactly the sent amount, except in the special case where the
        // block number is divisible by 15, in which case the full balance is forwarded to the caller.
        if (!reverted) {
            assert(newTimestamp > prevTimestamp || block.number == 0);
            if (block.number % 15 == 0) {
                // The whole prior balance plus the sent amount was sent to the caller, so c's balance is zero.
                assert(cBalanceAfter == 0);
            } else {
                assert(cBalanceAfter == cBalanceBefore + amount);
            }
        } else {
            // If the call reverted, it must be because the timestamp was not newer than the last
            // recorded one. In all other cases the call succeeds.
            assert(block.timestamp <= prevTimestamp);
        }
    }

    receive() external payable {}

    function noop() external {}
}

